(()=>{
  const $=s=>document.querySelector(s);const {formatPesos,parsePesos,makeResearchPrompt,summarizeSearch,connectionNext,validateRadarPassword}=window.RadarWizard;
  let configured=false,selected=null,timer=null,step=1,pendingFacebook=false,browserTimer=null;let requestedJob=new URLSearchParams(window.location.search).get('job');if(!/^[0-9a-f-]{36}$/i.test(requestedJob||''))requestedJob=null;let connection={loaded:false,secureControl:false,authenticated:false};
  async function api(path,opt={}){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),15000);try{const r=await fetch(path,{...opt,signal:controller.signal,headers:{'content-type':'application/json',...(opt.headers||{})}});const b=await r.json();if(!r.ok)throw Error(b.error||'No se pudo completar la operación.');return b;}catch(e){if(e.name==='AbortError')throw Error('La conexión tardó demasiado. Comprueba Tailscale e inténtalo de nuevo.');if(e.name==='TypeError')throw Error('No se pudo conectar con Radar. Comprueba Tailscale e inténtalo de nuevo.');throw e}finally{clearTimeout(timeout)}}
  function error(el,msg){el.textContent=msg;el.hidden=!msg;}
  let themeDirty=false,themeSaving=false,themeRevision=0,currentJob=null,cancellingId=null,progressSignature='';
  function applyTheme(theme){const dark=theme==='dark';document.documentElement.dataset.theme=dark?'dark':'light';$('#themeToggle').setAttribute('aria-label',dark?'Cambiar a modo claro':'Cambiar a modo oscuro');$('#themeToggle').setAttribute('aria-pressed',String(dark));$('#themeToggle .theme-label').textContent=dark?'Claro':'Oscuro';document.querySelector('meta[name="theme-color"]').content=dark?'#0b0e14':'#f6f8fb'}
  async function persistTheme(){if(!connection.authenticated||themeSaving)return;themeSaving=true;try{while(themeDirty&&connection.authenticated){const theme=document.documentElement.dataset.theme;themeDirty=false;try{await api('/api/preferences',{method:'PUT',body:JSON.stringify({theme})});error($('#themeError'),'')}catch(e){themeDirty=true;error($('#themeError'),'No se pudo guardar el tema. '+e.message);break}}}finally{themeSaving=false}}
  async function loadTheme(){const revision=themeRevision;try{const saved=await api('/api/preferences');if(revision===themeRevision&&!themeDirty&&!themeSaving&&['light','dark'].includes(saved.theme))applyTheme(saved.theme);if(themeDirty)persistTheme()}catch(e){error($('#themeError'),'No se pudo cargar el tema guardado. '+e.message)}}
  applyTheme(document.documentElement.dataset.theme||'light');
  $('#themeToggle').addEventListener('click',()=>{themeRevision++;applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');themeDirty=true;persistTheme()});

  function showView(name){for(const id of ['wizardView','browserView','jobContent'])$('#'+id).hidden=id!==name;}
  function closeBrowser(){clearTimeout(browserTimer);if(!$('#browserView').hidden){$('#browserFrame').src='about:blank';$('#browserView').hidden=true;}}
  function values(){return {category:document.querySelector('input[name="category"]:checked').value,query:$('#queryTask').value,location:$('#locationTask').value,min:$('#minTask').value,max:$('#maxTask').value,rental:$('#rentalTask').value,details:$('#detailsTask').value};}
  function updateStep(){const info=[['¿Qué necesitas buscar?','Elige una categoría y escribe lo que necesitas.'],['¿Dónde y por cuánto?','Indica la zona y el presupuesto que te interesan.'],['Dale los últimos detalles','Añade lo que quieres que revise el asistente.']][step-1];$('#stepCounter').textContent=`PASO ${step} DE 3`;$('#wizardHeading').textContent=info[0];$('#wizardSubtitle').textContent=info[1];document.querySelectorAll('.wizard-step').forEach(e=>e.hidden=+e.dataset.step!==step);$('#stepBack').hidden=step===1;$('#stepNext').hidden=step===3;$('#startTask').hidden=step!==3;$('#wizardView').dataset.step=String(step);document.querySelector('.step-track').setAttribute('aria-valuenow',step);document.querySelectorAll('.step-track span').forEach((e,i)=>{e.classList.toggle('current',i<step);e.classList.toggle('done',i<step-1)});$('#rentalLabel').hidden=values().category!=='Vivienda';if(step===3){try{$('#taskSummary').textContent=summarizeSearch(values())}catch(e){error($('#taskError'),e.message)}}}
  function freshSearch(){closeBrowser();$('#taskForm').reset();selected=null;const url=new URL(window.location.href);url.searchParams.delete('job');history.replaceState(null,'',url);step=1;error($('#taskError'),'');showView('wizardView');updateStep();renderSelection();}
  function renderSelection(){document.querySelectorAll('.job-button').forEach(b=>{const active=b.dataset.id===selected;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','true');else b.removeAttribute('aria-current')});}
  async function refreshFacebookStatus(){try{const d=await api('/api/facebook/status');$('#facebookLabel').textContent=d.savedSession?'Facebook: sesión guardada':'Conectar Facebook';$('#facebookStatus').textContent=d.savedSession?'Revisar sesión o cambiar zona':d.available?'Inicia sesión para buscar en Marketplace':'Navegador no disponible';$('#quickConnect').textContent=d.savedSession?'Sesión de Facebook guardada':'Conectar Facebook';}catch{$('#facebookStatus').textContent='No se pudo verificar la sesión';}}
  async function status(){try{const d=await api('/api/status');connection={loaded:true,secureControl:d.secureControl,authenticated:d.authenticated};configured=d.configured;document.querySelector('.auth-view .step-tag').textContent=configured?'ACCESO A RADAR':'PRIMER ACCESO';if(!d.secureControl){$('#authBox').hidden=false;$('#agentApp').hidden=true;$('#authTitle').textContent='Abre la conexión segura';$('#authDescription').textContent='Para entrar desde cualquier dispositivo, conecta Tailscale y abre el acceso privado.';$('#authForm').hidden=true;if(d.secureUrl&&!$('#secureLink')){try{const u=new URL(d.secureUrl);if(['http:','https:'].includes(u.protocol)&&!u.username&&!u.password){const a=document.createElement('a');a.id='secureLink';a.className='primary-button secure-link';a.href=u.href;a.textContent='Abrir acceso privado →';$('#authDescription').after(a)}}catch{}}return}$('#authForm').hidden=false;$('#authBox').hidden=d.authenticated;$('#agentApp').hidden=!d.authenticated;$('#authTitle').textContent=configured?'Entrar a Radar':'Protege tu espacio';$('#authDescription').textContent=configured?'Ingresa tu contraseña de Radar para continuar.':'Primero crea una contraseña para Radar. Después podrás conectar Facebook y comenzar tu búsqueda paso a paso.';$('#authButton').textContent=configured?'Ingresar':'Crear contraseña y continuar';$('#password').autocomplete=configured?'current-password':'new-password';$('#logout').hidden=!d.authenticated;if(d.authenticated){$('#connectionHint').hidden=true;loadTheme();refreshFacebookStatus();await loadJobs();updateStep();if(requestedJob){const id=requestedJob;requestedJob=null;await openJob(id)}if(pendingFacebook){pendingFacebook=false;openFacebook()}}}catch(e){$('#authTitle').textContent='No se pudo conectar';$('#authDescription').textContent='Revisa la conexión con el NAS y vuelve a cargar la página.';$('#authForm').hidden=true;}}
  $('#authForm').addEventListener('submit',async e=>{e.preventDefault();const pass=$('#password').value;const message=validateRadarPassword(pass);if(message){error($('#authError'),message);$('#password').focus();return}const button=$('#authButton');button.disabled=true;button.textContent='Conectando…';error($('#authError'),'');try{await api(configured?'/api/login':'/api/setup',{method:'POST',body:JSON.stringify({password:pass})});$('#password').value='';await status()}catch(e){error($('#authError'),e.name==='TimeoutError'?'La conexión tardó demasiado. Comprueba Tailscale e inténtalo de nuevo.':e.name==='TypeError'?'No se pudo conectar con Radar. Comprueba Tailscale e inténtalo de nuevo.':e.message)}finally{button.disabled=false;button.textContent=configured?'Ingresar':'Crear contraseña y continuar'}});
  function openFacebook(){clearTimeout(browserTimer);showView('browserView');$('#browserLoading').hidden=false;$('#browserRetry').hidden=true;$('#browserLoading').textContent='Conectando con Facebook…';$('#browserFrame').src='/browser';browserTimer=setTimeout(()=>{if(!$('#browserView').hidden){$('#browserLoading').textContent='La conexión está tardando. Comprueba Tailscale o vuelve a intentarlo.';$('#browserRetry').hidden=false}},20000)}
  $('#quickConnect').addEventListener('click',()=>$('#browserOpen').click());
  $('#locationConnect').addEventListener('click',()=>$('#browserOpen').click());
  $('#browserOpen').addEventListener('click',()=>{const next=connectionNext(connection);if(next==='open')return openFacebook();pendingFacebook=true;if(next==='authenticate'){const hint=$('#connectionHint');hint.textContent=configured?'Ingresa a Radar para abrir Facebook.':'Para conectar Facebook, primero crea tu contraseña de Radar. Después se abrirá Facebook automáticamente.';hint.hidden=false;$('#authBox').scrollIntoView({behavior:'smooth',block:'center'});$('#password').focus()}else if(next==='secure'){const hint=$('#connectionHint');hint.textContent='Primero abre la conexión segura para poder entrar a Facebook.';hint.hidden=false;$('#secureLink')?.focus()}else{const hint=$('#connectionHint');hint.textContent='Preparando la conexión. Si tarda demasiado, vuelve a cargar la página.';hint.hidden=false;}});
  $('#browserFrame').addEventListener('load',()=>{if(!$('#browserView').hidden){clearTimeout(browserTimer);$('#browserLoading').textContent='Si aún no ves Facebook, espera unos segundos.';$('#browserRetry').hidden=false}});
  $('#browserRetry').addEventListener('click',openFacebook);
  $('#browserKeyboard').addEventListener('click',()=>{try{const doc=$('#browserFrame').contentDocument;const button=doc?.getElementById('noVNC_keyboard_button');if(button)button.click();else throw Error('Espera a que termine la conexión para abrir el teclado.')}catch(e){$('#browserLoading').textContent=e.message||'Espera a que termine la conexión para abrir el teclado.'}});
  $('#browserClose').addEventListener('click',()=>{closeBrowser();showView('wizardView');updateStep();setTimeout(refreshFacebookStatus,500)});
  $('#logout').addEventListener('click',async()=>{closeBrowser();await api('/api/logout',{method:'POST',body:'{}'});clearTimeout(timer);selected=null;$('#jobs').replaceChildren();$('#historyHint').hidden=false;await status()});
  $('#newSearch').addEventListener('click',()=>{if(connectionNext(connection)==='open')return freshSearch();pendingFacebook=false;const hint=$('#connectionHint');hint.textContent=connection.secureControl?'Para crear una búsqueda, primero entra a Radar.':'Abre primero la conexión segura de Radar.';hint.hidden=false;if(connection.secureControl)$('#password').focus();else $('#secureLink')?.focus()});
  document.querySelectorAll('input[name="category"]').forEach(el=>el.addEventListener('change',()=>{const placeholders={'Vivienda':'Ej.: apartamento en venta','Tecnología':'Ej.: MacBook M2 o PlayStation 5','Vehículos':'Ej.: carro automático','Otros':'Ej.: bicicleta de montaña'};$('#queryTask').placeholder=placeholders[values().category];$('#maxTask').placeholder=({'Vivienda':'130.000.000','Tecnología':'2.000.000','Vehículos':'20.000.000','Otros':'Sin límite'})[values().category];$('#rentalLabel').hidden=values().category!=='Vivienda'}));
  document.querySelectorAll('[data-suggest]').forEach(button=>button.addEventListener('click',()=>{const category=[...document.querySelectorAll('input[name="category"]')].find(input=>input.value===button.dataset.category);if(category){category.checked=true;category.dispatchEvent(new Event('change',{bubbles:true}))}$('#queryTask').value=button.dataset.suggest;$('#queryTask').focus()}));
  document.querySelectorAll('[data-detail]').forEach(button=>button.addEventListener('click',()=>{const field=$('#detailsTask'),text=button.dataset.detail;if(!field.value.includes(text))field.value=[field.value.trim(),text].filter(Boolean).join(' ');field.focus()}));
  function filterHistory(){const query=$('#historySearch').value.trim().toLocaleLowerCase('es');const rows=[...document.querySelectorAll('.job-row')];let visible=0;for(const row of rows){row.hidden=!!query&&!row.dataset.search.includes(query);if(!row.hidden)visible++}$('#historyHint').hidden=visible>0;$('#historyHint').textContent=query?'No encontramos búsquedas con ese texto.':'Tus búsquedas aparecerán aquí.'}
  $('#historySearch').addEventListener('input',filterHistory);
  $('#stepBack').addEventListener('click',()=>{step=Math.max(1,step-1);error($('#taskError'),'');updateStep()});
  $('#stepNext').addEventListener('click',()=>{try{if(step===1&&values().query.trim().length<2)throw Error('Escribe qué quieres buscar.');if(step===2){const v=values(),min=parsePesos(v.min),max=parsePesos(v.max);if(min!==null&&max!==null&&min>max)throw Error('El presupuesto mínimo supera al máximo.')}step=Math.min(3,step+1);error($('#taskError'),'');updateStep()}catch(e){error($('#taskError'),e.message)}});
  $('#taskForm').addEventListener('submit',async e=>{e.preventDefault();if(step!==3)return;$('#startTask').disabled=true;try{const prompt=makeResearchPrompt(values());const d=await api('/api/jobs',{method:'POST',body:JSON.stringify({prompt})});selected=d.id;error($('#taskError'),'');await loadJobs();await openJob(selected)}catch(e){error($('#taskError'),e.message)}finally{$('#startTask').disabled=false}});
  async function deleteJob(job){
    error($('#historyError'),'');
    if(['ejecutando','en cola'].includes(job.status)){error($('#historyError'),'Primero detén esta investigación y espera a que termine para eliminarla.');return}
    if(!window.confirm('¿Eliminar esta búsqueda y su informe? Esta acción no se puede deshacer.'))return;
    try{await api('/api/jobs/'+job.id,{method:'DELETE'});if(selected===job.id)freshSearch();await loadJobs()}
    catch(e){error($('#historyError'),e.message)}
  }
  async function loadJobs(){clearTimeout(timer);try{const data=await api('/api/jobs');$('#historyHint').hidden=!!data.jobs.length;const box=$('#jobs');box.replaceChildren();for(const job of data.jobs){
    const row=document.createElement('div');row.className='job-row';row.dataset.search=job.prompt.toLocaleLowerCase('es');
    const b=document.createElement('button');b.type='button';b.className='job-button';b.dataset.id=job.id;
    const title=document.createElement('strong');title.textContent=job.prompt.replace(/^Busca oportunidades de /,'').split(' en Facebook Marketplace')[0].slice(0,78);
    const detail=document.createElement('small');detail.textContent=job.status+' · '+new Date(job.created).toLocaleDateString('es-CO');b.append(title,detail);b.addEventListener('click',()=>openJob(job.id));
    const remove=document.createElement('button');remove.type='button';remove.className='job-delete';remove.setAttribute('aria-label','Eliminar búsqueda: '+title.textContent);remove.title='Eliminar búsqueda';
    const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');
    const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d','M4 7h16M9 7V4h6v3m3 0-1 13H7L6 7m4 4v5m4-5v5');svg.append(path);remove.append(svg);remove.addEventListener('click',()=>deleteJob(job));
    row.append(b,remove);box.append(row)
  }$('#historyCount').textContent=data.jobs.length?data.jobs.length+(data.jobs.length===1?' búsqueda guardada':' búsquedas guardadas'):'Sin búsquedas todavía';filterHistory();renderSelection();if(selected)await loadJob();timer=setTimeout(loadJobs,data.jobs.some(x=>['ejecutando','en cola'].includes(x.status))?5000:30000)}catch(e){error($('#historyError'),e.message);if(currentJob&&['en cola','ejecutando'].includes(currentJob.status))error($('#liveSyncError'),'No se pudo actualizar el avance. '+e.message);if(connection.authenticated)timer=setTimeout(loadJobs,30000)}}

  function clearReport(){currentJob=null;progressSignature='';$('#liveProgress').hidden=true;error($('#liveSyncError'),'');$('#jobTitle').textContent='Cargando investigación…';$('#jobStatus').textContent='Cargando';$('#jobReport').replaceChildren();$('#jobProgress').replaceChildren();$('#reportStats').replaceChildren();$('#reportStats').hidden=true;$('#reportHighlights').replaceChildren();$('#highlightsSection').hidden=true;$('#reportHeading').hidden=true;$('#reportPlaceholder').hidden=false;$('#rerunJob').hidden=true;$('#printReport').hidden=true;$('#cancelJob').hidden=true;error($('#jobError'),'')}
  async function openJob(id){closeBrowser();selected=id;clearReport();showView('jobContent');renderSelection();try{await loadJob();if(selected!==id)return;const url=new URL(window.location.href);url.searchParams.set('job',id);history.replaceState(null,'',url);$('#jobContent').scrollIntoView({behavior:'smooth',block:'start'})}catch(e){if(selected!==id)return;freshSearch();error($('#historyError'),e.message)}}
  function reportText(root,text){window.RadarReport.render(root,text)}
  function updateReportDetails(report){
    const stats=$('#reportStats');stats.replaceChildren();const source=String(report||'');
    const pairs=[['Anuncios encontrados',source.match(/Resultados:\s*(\d+)\s+anuncios únicos/i)?.[1]],['Anuncios abiertos',source.match(/;\s*(\d+)\s+anuncios? abiertos?/i)?.[1]],['Desplazamientos',source.match(/Recorrido:\s*(\d+)\s+desplazamientos/i)?.[1]]];
    for(const [label,value] of pairs){if(value===undefined)continue;const card=document.createElement('div');card.className='report-stat surface';const caption=document.createElement('span');caption.textContent=label;const number=document.createElement('strong');number.textContent=new Intl.NumberFormat('es-CO').format(Number(value));card.append(caption,number);stats.append(card)}stats.hidden=!stats.children.length;
    const box=$('#reportHighlights');box.replaceChildren();const highlights=window.RadarReport.highlights?.($('#jobReport'))||[];
    for(const item of highlights){const card=document.createElement('article');card.className='highlight-card surface';const label=document.createElement('span');label.className='highlight-label';label.textContent=(item.source||'ENLACE DEL INFORME').toLocaleUpperCase('es-CO');const title=document.createElement('h3');title.textContent=item.title;const link=document.createElement('a');link.href=item.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Ver publicación ↗';card.append(label,title,link);box.append(card)}$('#highlightsSection').hidden=!highlights.length;
  }
  function renderLiveProgress(j){
    const p=window.RadarProgress.derive(j);$('#liveProgress').hidden=!p.active;if(!p.active)return;
    $('#livePhase').textContent=p.phase;
    $('#liveDescription').textContent=j.status==='en cola'?'Tu búsqueda está en espera. Radar la iniciará cuando pueda.':'Radar está investigando. Este panel se actualiza automáticamente.';
    $('#liveElapsed').textContent=p.elapsed||'—';
    $('#liveFoundMetric').hidden=p.found===null;
    if(p.found!==null){$('#liveBatchLabel').textContent=p.batchLabel;$('#liveFound').textContent=new Intl.NumberFormat('es-CO').format(p.found);$('#livePasses').textContent=p.passes!==null?`${p.passes} pasadas registradas`:p.scrolls!==null?`${p.scrolls} desplazamientos registrados`:''}
    $('#liveQueryMetric').hidden=!p.queryRequests;$('#liveQueryRequests').textContent=String(p.queryRequests);
    $('#liveReadMetric').hidden=!p.readRequests;$('#liveReadRequests').textContent=String(p.readRequests);
    $('#liveLatest').textContent=p.latest||'Esperando la primera actualización.';
    const date=p.latestAt?new Date(p.latestAt):null;$('#liveUpdated').textContent=date&&!Number.isNaN(date.valueOf())?date.toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}):'';
  }
  setInterval(()=>{if(currentJob&&!$('#jobContent').hidden&&['en cola','ejecutando'].includes(currentJob.status))$('#liveElapsed').textContent=window.RadarProgress.derive(currentJob).elapsed||'—'},1000);
  function renderActivity(j){
    const events=Array.isArray(j.progress)?j.progress.slice(-80):[],signature=JSON.stringify([j.id,events]);if(signature===progressSignature)return;progressSignature=signature;
    const box=$('#jobProgress'),scroll=box.scrollTop,fragment=document.createDocumentFragment();
    for(const event of events.slice().reverse()){const row=document.createElement('div');row.className='activity-entry';const time=document.createElement('time'),date=event.at?new Date(event.at):null;if(date&&!Number.isNaN(date.valueOf()))time.textContent=date.toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit',hour12:false});const text=document.createElement('span');text.textContent=event.text||'';row.append(time,text);fragment.append(row)}
    box.replaceChildren(fragment);box.scrollTop=scroll;
  }
  async function loadJob(){
    const id=selected,j=await api('/api/jobs/'+id);if(selected!==id)return;currentJob=j;
    const active=['en cola','ejecutando'].includes(j.status);if(cancellingId===id&&!active)cancellingId=null;
    $('#rerunJob').hidden=active;$('#printReport').hidden=!j.report;$('#jobTitle').textContent=j.prompt.replace(/^Busca oportunidades de /,'').split(' en Facebook Marketplace')[0];$('#jobStatus').textContent=j.status;
    const cancel=$('#cancelJob');cancel.hidden=!active;cancel.disabled=cancellingId===id;cancel.textContent=cancel.disabled?'Deteniendo…':'Detener investigación';
    renderLiveProgress(j);renderActivity(j);error($('#liveSyncError'),'');error($('#jobError'),j.error||'');$('#reportHeading').hidden=!j.report;$('#reportPlaceholder').hidden=!!j.report;reportText($('#jobReport'),j.report||'');updateReportDetails(j.report)
  }
  $('#printReport').addEventListener('click',()=>window.print());
  $('#rerunJob').addEventListener('click',async()=>{if(!currentJob)return;const button=$('#rerunJob');button.disabled=true;try{const result=await api('/api/jobs',{method:'POST',body:JSON.stringify({prompt:currentJob.prompt})});await loadJobs();await openJob(result.id)}catch(e){error($('#jobError'),e.message)}finally{button.disabled=false}});
  $('#cancelJob').addEventListener('click',async()=>{if(!selected||cancellingId===selected)return;const id=selected,button=$('#cancelJob');cancellingId=id;button.disabled=true;button.textContent='Deteniendo…';try{await api('/api/jobs/'+id+'/cancel',{method:'POST',body:'{}'});await loadJobs()}catch(e){if(cancellingId===id)cancellingId=null;if(selected===id){button.disabled=false;button.textContent='Detener investigación';error($('#liveSyncError'),e.message)}}});
  for(const input of document.querySelectorAll('.currency-input')){input.addEventListener('input',()=>{const caret=input.selectionStart,numberBefore=input.value.slice(0,caret).replace(/\D/g,'').length;try{input.value=formatPesos(input.value);let pos=0,count=0;while(pos<input.value.length&&count<numberBefore){if(/\d/.test(input.value[pos]))count++;pos++}input.setSelectionRange(pos,pos)}catch{input.value=input.value.replace(/\D/g,'').slice(0,15);input.value=formatPesos(input.value)}})}
  window.addEventListener('radar:navigate',e=>{if(e.detail==='facebook'){$('#browserOpen').click();if(!$('#browserView').hidden)$('#browserView').scrollIntoView({behavior:'smooth',block:'start'})}else if(e.detail==='history'){if(connection.authenticated)loadJobs();document.querySelector('.history-panel').scrollIntoView({behavior:'smooth',block:'start'})}else if(connection.authenticated){closeBrowser();showView('wizardView');updateStep();$('#wizardView').scrollIntoView({behavior:'smooth',block:'start'})}else{$('#authBox').scrollIntoView({behavior:'smooth',block:'center'})}});
  window.addEventListener('focus',()=>{if(connection.authenticated)loadJobs()});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden&&connection.authenticated)loadJobs()});
  updateStep();status();
})();
